  var GROEP = { i: 'Instrumenten', t: 'Indicatoren belicht', k: 'Indicatoren belicht', r: 'Registraties belicht', o: 'Over de site' };
  var W = { n: 10, w: 7, x: 4, m: 2 };
  var BONUS = { i: 4, t: 3, r: 2, o: 0, k: -0.5 };   // bij gelijke treffer eerst het instrument, dan het thema, dan de kaart

  var norm = function (s) { return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim(); };
  L.forEach(function (it) { it._ = { n: ' ' + norm(it.n) + ' ', w: ' ' + norm(it.w) + ' ', x: ' ' + norm(it.x) + ' ', m: ' ' + norm(it.m) + ' ' }; });
  var esc = function (s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); };

  function zoek(q) {
    var ts = norm(q).split(' ').filter(Boolean);
    if (!ts.length) return [];
    var uit = [];
    L.forEach(function (it) {
      var tot = 0;
      for (var i = 0; i < ts.length; i++) {
        var t = ts[i], best = 0, som = 0;
        for (var f in W) {
          var v = it._[f], s = 0;
          if (v.indexOf(' ' + t + ' ') >= 0) s = W[f];
          else if (v.indexOf(' ' + t) >= 0) s = W[f] * 0.75;
          else if (t.length >= 4 && v.indexOf(t) >= 0) s = W[f] * 0.5;
          else if (t.length >= 6 && v.indexOf(t.slice(0, t.length - 2)) >= 0) s = W[f] * 0.35;
          if (s > best) best = s;
          som += s;
        }
        if (!best) return;
        tot += best + 0.15 * (som - best);   // telt het woord op meer plekken, dan iets hoger
      }
      tot += BONUS[it.t] || 0;
      uit.push({ it: it, s: tot });
    });
    uit.sort(function (a, b) { return b.s - a.s || a.it.n.localeCompare(b.it.n, 'nl'); });
    var per = {};   // hoogstens zes per onderdeel, zodat een instrument niet onder twintig kaarten verdwijnt
    return uit.filter(function (r) { var g = GROEP[r.it.t]; per[g] = (per[g] || 0) + 1; return per[g] <= 6; }).map(function (r) { return r.it; });
  }

